<?php require 'db.php';require_login();$error=null;$ok=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$s=$pdo->prepare('SELECT password_hash FROM users WHERE user_id=?');$s->execute([current_user()['user_id']]);$hash=$s->fetchColumn();if(!password_verify($current,$hash))$error='Current password is incorrect.';elseif(strlen($new)<8||!preg_match('/[A-Z]/',$new)||!preg_match('/[a-z]/',$new)||!preg_match('/\d/',$new))$error='New password must be 8+ characters with uppercase, lowercase and a number.';elseif($new!==$confirm)$error='New passwords do not match.';else{$s=$pdo->prepare('UPDATE users SET password_hash=? WHERE user_id=?');$s->execute([password_hash($new,PASSWORD_BCRYPT),current_user()['user_id']]);$ok='Password changed successfully.';}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Change Password | Ceylon Spice Hub</title><link rel="stylesheet" href="style.css"></head><body><main class="auth-page"><div class="auth-card"><a class="text-link" href="profile.php">← Back to profile</a><p class="eyebrow">ACCOUNT SECURITY</p><h1>Change password</h1><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><?php if($ok):?><div class="form-success"><?=e($ok)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Current Password<input type="password" name="current_password" required></label><label>New Password<input type="password" name="new_password" required minlength="8"></label><label>Confirm New Password<input type="password" name="confirm_password" required></label><button class="btn btn-primary auth-submit">UPDATE PASSWORD</button></form></div></main></body></html>